    {
      "card_ids": ["C01"],
      "claim": "WAY-100634, which shares the 2-methoxyphenylpiperazine core and a basic amine side chain, showed avid brain uptake in a cynomolgus monkey after IV injection, comparable to WAY-100635; this directly supports meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "The iodinated BPB analogue, retaining the same methoxyphenylpiperazine scaffold, reached 4.99% ID/g in mouse brain at 10 min, demonstrating high BBB permeability and supporting CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "FECUMI-101, a close heterocycle-dione analogue with a piperazine aryl ether and butyl linker, effectively crossed the BBB in baboon PET studies, supporting the CNS-penetrant nature of the query's uracil-containing tail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "The [11C]10 triazinedione analogue penetrated the BBB in baboons with regional brain uptake matching 5-HT1A receptor distribution, providing direct evidence that this structural family enters the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A structurally related dimethylaminobenzamide analogue showed low brain uptake in rats and was identified as an ABC efflux substrate; however, its benzamide/dimethylamino tail differs from the query's uracil tail and is outweighed by multiple positive in vivo analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass. Multiple direct in vivo brain-uptake and PET studies on close 2-methoxyphenylpiperazine analogues, including triazinedione/uracil-type heterocycles, demonstrate meaningful CNS access; the single efflux-substrate negative has a different tail and is outweighed.",
  "evidence_gaps": [
    "No direct brain/plasma or PET measurement for the exact query molecule",
    "Efflux-transporter status of the uracil-containing tail is not directly measured",
    "No human CSF or brain exposure data for the query"
  ],
